        m = len(merged)
        if m <= 1:
            return m

        starts = [iv[0] for iv in merged]
        max_reduced = 0

        # 2. For each merged interval, inserting interval of length k starting at merged[i][1]
        for i in range(m):
            reach = merged[i][1] + k
            j = bisect_right(starts, reach) - 1
            if j > i:
                max_reduced = max(max_reduced, j - i)

