#include <vector>
#include <algorithm>

class Solution {
public:
    int minConnectedGroups(std::vector<std::vector<int>>& intervals, int k) {
        std::sort(intervals.begin(), intervals.end());
        std::vector<std::pair<int, int>> merged;
        for (const auto& iv : intervals) {
            if (merged.empty() || merged.back().second < iv[0]) {
                merged.push_back({iv[0], iv[1]});
            } else {
                merged.back().second = std::max(merged.back().second, iv[1]);
            }
        }

        int m = merged.size();
        if (m <= 1) return m;

        std::vector<int> starts;
        for (const auto& p : merged) starts.push_back(p.first);

        int max_reduced = 0;
        for (int i = 0; i < m; ++i) {
            int reach = merged[i].second + k;
            auto it = std::upper_bound(starts.begin(), starts.end(), reach);
            int j = std::distance(starts.begin(), it) - 1;
            if (j > i) {
                max_reduced = std::max(max_reduced, j - i);
            }
        }
        return m - max_reduced;
    }
};

import java.util.*;

class Solution {
    public int minConnectedGroups(int[][] intervals, int k) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] iv : intervals) {
            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < iv[0]) {
                merged.add(new int[]{iv[0], iv[1]});
            } else {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);
            }
        }

        int m = merged.size();
        if (m <= 1) return m;

        int[] starts = new int[m];
        for (int i = 0; i < m; i++) starts[i] = merged.get(i)[0];

        int maxReduced = 0;
        for (int i = 0; i < m; i++) {
            int reach = merged.get(i)[1] + k;
            int idx = Arrays.binarySearch(starts, reach);
            int j;
            if (idx >= 0) {
                while (idx + 1 < m && starts[idx + 1] == reach) idx++;
                j = idx;
            } else {
                j = -(idx + 1) - 1;
            }
            if (j > i) {
                maxReduced = Math.max(maxReduced, j - i);
            }
        }
        return m - maxReduced;
    }
}

var minConnectedGroups = function(intervals, k) {
    intervals.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const iv of intervals) {
        if (merged.length === 0 || merged[merged.length - 1][1] < iv[0]) {
            merged.push([iv[0], iv[1]]);
        } else {
            merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], iv[1]);
        }
    }

    const m = merged.length;
    if (m <= 1) return m;

    const starts = merged.map(x => x[0]);
    let maxReduced = 0;

    for (let i = 0; i < m; i++) {
        const reach = merged[i][1] + k;
        let low = 0, high = m - 1, j = i;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (starts[mid] <= reach) {
                j = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        if (j > i) {
            maxReduced = Math.max(maxReduced, j - i);
        }
    }
    return m - maxReduced;
};
